BEGIN;
CREATE EXTENSION IF NOT EXISTS btree_gist WITH SCHEMA extensions;
CREATE SCHEMA IF NOT EXISTS private;
REVOKE ALL ON SCHEMA private FROM PUBLIC, anon, authenticated;
GRANT USAGE ON SCHEMA private TO authenticated;

CREATE TABLE public.departments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,code text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.campuses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,address text,active boolean NOT NULL DEFAULT true);
CREATE TABLE public.academic_terms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,starts_on date NOT NULL,ends_on date NOT NULL,CHECK(ends_on>=starts_on));
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,full_name text NOT NULL,email text,phone text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.student_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE RESTRICT,student_no text NOT NULL UNIQUE,department_id uuid NOT NULL REFERENCES public.departments(id) ON DELETE RESTRICT,enrollment_year int NOT NULL CHECK(enrollment_year BETWEEN 1950 AND 2200),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','graduated','suspended','withdrawn')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.hostels(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campus_id uuid NOT NULL REFERENCES public.campuses(id) ON DELETE RESTRICT,name text NOT NULL,address text,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(campus_id,name));
CREATE TABLE public.staff_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,campus_id uuid REFERENCES public.campuses(id) ON DELETE RESTRICT,hostel_id uuid REFERENCES public.hostels(id) ON DELETE RESTRICT,role text NOT NULL CHECK(role IN ('admin','warden','maintenance','finance')),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),CHECK(role NOT IN ('warden','maintenance') OR hostel_id IS NOT NULL));
CREATE INDEX staff_user_role_idx ON public.staff_assignments(user_id,role) WHERE active;
CREATE TABLE public.rooms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hostel_id uuid NOT NULL REFERENCES public.hostels(id) ON DELETE RESTRICT,room_number text NOT NULL,floor_number int,room_type text NOT NULL DEFAULT 'standard',capacity int NOT NULL CHECK(capacity>0),accessible boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','maintenance','inactive')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(hostel_id,room_number));
CREATE TABLE public.beds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),room_id uuid NOT NULL REFERENCES public.rooms(id) ON DELETE RESTRICT,bed_number text NOT NULL,status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','maintenance','inactive')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(room_id,bed_number));
CREATE TABLE public.room_applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES public.student_records(id) ON DELETE RESTRICT,term_id uuid NOT NULL REFERENCES public.academic_terms(id) ON DELETE RESTRICT,preferred_hostel_id uuid REFERENCES public.hostels(id) ON DELETE RESTRICT,notes text,status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('draft','submitted','under_review','approved','rejected','withdrawn')),reviewed_by uuid REFERENCES public.profiles(id) ON DELETE RESTRICT,reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(student_id,term_id),CHECK((reviewed_by IS NULL)=(reviewed_at IS NULL)));
CREATE TABLE public.allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES public.student_records(id) ON DELETE RESTRICT,bed_id uuid NOT NULL REFERENCES public.beds(id) ON DELETE RESTRICT,application_id uuid UNIQUE REFERENCES public.room_applications(id) ON DELETE RESTRICT,start_date date NOT NULL,end_date date,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','completed','cancelled')),allocated_by uuid REFERENCES public.profiles(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),CHECK(end_date IS NULL OR end_date>start_date),CONSTRAINT allocation_bed_no_overlap EXCLUDE USING gist(bed_id WITH =,daterange(start_date,end_date,'[)') WITH &&) WHERE(status='active'),CONSTRAINT allocation_student_no_overlap EXCLUDE USING gist(student_id WITH =,daterange(start_date,end_date,'[)') WITH &&) WHERE(status='active'));
CREATE INDEX allocations_student_idx ON public.allocations(student_id,start_date DESC);
CREATE TABLE public.fee_invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES public.student_records(id) ON DELETE RESTRICT,term_id uuid REFERENCES public.academic_terms(id) ON DELETE RESTRICT,invoice_number text NOT NULL UNIQUE,amount numeric(12,2) NOT NULL CHECK(amount>=0),currency text NOT NULL DEFAULT 'INR' CHECK(currency ~ '^[A-Z]{3}$'),due_date date NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','partial','paid','overdue','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX invoices_student_status_idx ON public.fee_invoices(student_id,status);
CREATE TABLE public.payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_id uuid NOT NULL REFERENCES public.fee_invoices(id) ON DELETE RESTRICT,amount numeric(12,2) NOT NULL CHECK(amount>0),provider text NOT NULL,provider_reference text,idempotency_key text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','successful','failed','refunded')),paid_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,provider_reference),CHECK(status<>'successful' OR paid_at IS NOT NULL));
CREATE TABLE public.payment_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),payment_id uuid NOT NULL REFERENCES public.payments(id) ON DELETE RESTRICT,provider_event_id text NOT NULL UNIQUE,event_type text NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.complaints(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES public.student_records(id) ON DELETE RESTRICT,room_id uuid REFERENCES public.rooms(id) ON DELETE RESTRICT,category text NOT NULL,description text NOT NULL CHECK(length(trim(description)) BETWEEN 1 AND 5000),status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','resolved','closed')),assigned_to uuid REFERENCES public.profiles(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE public.maintenance_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),room_id uuid NOT NULL REFERENCES public.rooms(id) ON DELETE RESTRICT,reported_by uuid REFERENCES public.profiles(id) ON DELETE RESTRICT,assigned_to uuid REFERENCES public.profiles(id) ON DELETE RESTRICT,description text NOT NULL CHECK(length(trim(description)) BETWEEN 1 AND 5000),priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','urgent')),status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','completed','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE public.leave_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES public.student_records(id) ON DELETE RESTRICT,from_time timestamptz NOT NULL,to_time timestamptz NOT NULL,reason text NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 2000),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','cancelled')),reviewed_by uuid REFERENCES public.profiles(id) ON DELETE RESTRICT,reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK(to_time>from_time),CHECK((reviewed_by IS NULL)=(reviewed_at IS NULL)));
CREATE TABLE public.visitors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),full_name text NOT NULL,phone text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.visitor_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),visitor_id uuid NOT NULL REFERENCES public.visitors(id) ON DELETE RESTRICT,student_id uuid NOT NULL REFERENCES public.student_records(id) ON DELETE RESTRICT,hostel_id uuid NOT NULL REFERENCES public.hostels(id) ON DELETE RESTRICT,entry_time timestamptz NOT NULL DEFAULT now(),exit_time timestamptz,recorded_by uuid REFERENCES public.profiles(id) ON DELETE RESTRICT,CHECK(exit_time IS NULL OR exit_time>=entry_time));
CREATE TABLE public.announcements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,body text NOT NULL,campus_id uuid REFERENCES public.campuses(id) ON DELETE RESTRICT,hostel_id uuid REFERENCES public.hostels(id) ON DELETE RESTRICT,published boolean NOT NULL DEFAULT false,published_at timestamptz,created_by uuid REFERENCES public.profiles(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),CHECK(hostel_id IS NULL OR campus_id IS NOT NULL),CHECK(NOT published OR published_at IS NOT NULL));
CREATE TABLE public.audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_id uuid,table_name text NOT NULL,record_id text NOT NULL,operation text NOT NULL CHECK(operation IN ('INSERT','UPDATE','DELETE')),old_data jsonb,new_data jsonb,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_record_idx ON public.audit_logs(table_name,record_id,occurred_at DESC);
CREATE INDEX maintenance_queue_idx ON public.maintenance_requests(status,priority,created_at);
CREATE INDEX visitor_open_entries_idx ON public.visitor_logs(hostel_id,entry_time) WHERE exit_time IS NULL;
COMMIT;
